#!/bin/sh
build_profile(){ p=$1; case $p in debug) flags='-O0 -g3'; jobs=1;; size) flags='-Os -ffunction-sections -fdata-sections'; jobs=2;; release) flags='-O2 -pipe'; jobs=2;; aggressive) flags='-O3 -pipe -flto'; jobs=4;; esac; replace_block "$CURRENT_HOME/.profile" build "export CFLAGS='$flags'\nexport CXXFLAGS='$flags'\nexport MAKEFLAGS='-j$jobs'\nexport CMAKE_BUILD_PARALLEL_LEVEL='$jobs'\nexport CARGO_BUILD_JOBS='$jobs'"; }
build_compilers_menu(){ while :; do c=$(ui_menu 'Build systems and compilers' 'Configure toolchains using iSH-AOK-safe profiles.' bundle 'Install C/C++ build bundle' profile 'Compiler optimization profile' make 'Make settings' cmake 'CMake settings' meson 'Meson settings' cargo 'Cargo build settings' compiler 'Select CC and CXX' ccache 'Configure ccache/sccache' test 'Compile test program' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in bundle) pkg_install build-essential cmake ninja-build meson pkg-config git 2>/dev/null || pkg_install build-base cmake ninja meson pkgconf git;; profile) p=$(ui_menu Profile 'Choose profile.' debug Debug size 'Optimize for size' release Balanced aggressive Aggressive) || continue; build_profile "$p";; make) j=$(ui_input Make 'Parallel jobs' 2) || continue; replace_block "$CURRENT_HOME/.profile" make "export MAKEFLAGS='-j$j'";; cmake) replace_block "$CURRENT_HOME/.profile" cmake 'export CMAKE_GENERATOR=Ninja\nexport CMAKE_BUILD_PARALLEL_LEVEL=${CMAKE_BUILD_PARALLEL_LEVEL:-2}';; meson) mkdir -p "$CURRENT_HOME/.config/meson"; edit_file "$CURRENT_HOME/.config/meson/native.ini";; cargo) mkdir -p "$CURRENT_HOME/.cargo"; config_entry_menu Cargo "$CURRENT_HOME/.cargo/config.toml" cargo;; compiler) cc=$(ui_menu Compiler 'Select compiler.' gcc GCC clang Clang tcc TinyCC) || continue; case $cc in gcc) cxx=g++;; clang) cxx=clang++;; tcc) cxx=tcc;; esac; replace_block "$CURRENT_HOME/.profile" compiler "export CC=$cc\nexport CXX=$cxx";; ccache) pkg_install ccache; replace_block "$CURRENT_HOME/.profile" ccache 'export CCACHE_DIR="$HOME/.cache/ccache"\nexport CC="ccache ${CC:-cc}"\nexport CXX="ccache ${CXX:-c++}"';; test) ensure_tool cc gcc || continue; cat >"$TMP_DIR/test.c" <<'EOF'
#include <stdio.h>
int main(void){puts("compiler works");return 0;}
EOF
run_capture Compiler sh -c "cc '$TMP_DIR/test.c' -o '$TMP_DIR/test' && '$TMP_DIR/test'";; back) return;; esac; done; }
